ARG BASE=debian:bookworm-slim
FROM ${BASE}
ARG CODEX_VERSION=0.156.1
ARG OMO_VERSION=4.19.4
ARG NODE_MAJOR=22
ENV DEBIAN_FRONTEND=noninteractive
RUN apt-get update && apt-get install -y --no-install-recommends ca-certificates curl xz-utils git bash procps && rm -rf /var/lib/apt/lists/*
RUN set -eux; arch="$(uname -m)"; case "$arch" in x86_64) narch=x64;; aarch64|arm64) narch=arm64;; *) echo "unsupported arch $arch" >&2; exit 1;; esac; \
    tarball="$(curl -fsSL "https://nodejs.org/dist/latest-v${NODE_MAJOR}.x/SHASUMS256.txt" | awk '{print $2}' | grep "linux-${narch}.tar.xz$")"; \
    mkdir -p /opt/harness/node /opt/harness/bin /opt/harness/shim /work; \
    curl -fsSL "https://nodejs.org/dist/latest-v${NODE_MAJOR}.x/${tarball}" | tar -xJ -C /opt/harness/node --strip-components=1
ENV PATH=/opt/harness/bin:/opt/harness/node/bin:$PATH
ENV CODEX_HOME=/opt/harness/codex-home
ENV npm_config_update_notifier=false
RUN npm install -g --no-fund --no-audit "@openai/codex@${CODEX_VERSION}" "oh-my-openagent@${OMO_VERSION}"
COPY . /opt/harness/src
RUN set -eux; mkdir -p "$CODEX_HOME" /opt/harness/work; cd /opt/harness/work; \
    node /opt/harness/src/bin/lazycodex-ai.js --dry-run install --no-tui --codex-autonomous; \
    CODEX_LOCAL_BIN_DIR=/opt/harness/bin OMO_CODEX_PROJECT=/opt/harness/work OMO_RUNTIME=node \
    OMO_DISABLE_POSTHOG=1 OMO_SEND_ANONYMOUS_TELEMETRY=0 CI=1 \
    omo install --platform=codex --no-tui --codex-autonomous </dev/null
RUN set -eux; cfg="$CODEX_HOME/config.toml"; \
    PLUGIN_ROOT="$(ls -d "$CODEX_HOME"/plugins/cache/sisyphuslabs/omo/*/ | head -n1)"; PLUGIN_ROOT="${PLUGIN_ROOT%/}"; \
    PLUGIN_ROOT="$PLUGIN_ROOT" PLUGIN_DATA="$CODEX_HOME/plugins/data/omo-sisyphuslabs" OMO_DISABLE_POSTHOG=1 OMO_SEND_ANONYMOUS_TELEMETRY=0 \
      node "$PLUGIN_ROOT/components/bootstrap/dist/cli.js" worker --once --codex-home "$CODEX_HOME" || echo "bootstrap pre-run degraded (continuing)"; \
    sed -i '/^network_access = /d' "$cfg"; \
    grep -q '^model_provider = ' "$cfg" || sed -i '0,/^model = /s//model_provider = "proxy"\nmodel = /' "$cfg"; \
    printf '%s\n' '' '[model_providers.proxy]' 'name = "recording proxy (via local Responses->Chat shim on 127.0.0.1:4141)"' 'base_url = "http://127.0.0.1:4141/v1"' 'env_key = "OPENAI_API_KEY"' 'wire_api = "responses"' 'request_max_retries = 2' 'stream_max_retries = 2' '' '[plugins."omo@sisyphuslabs".mcp_servers.grep_app]' 'enabled = false' >> "$cfg"; \
    sed -i '/^\[plugins."omo@sisyphuslabs".mcp_servers.context7\]/,/^$/ s/^enabled = true/enabled = false/' "$cfg"; \
    chmod -R a+rwX "$CODEX_HOME" /work
COPY <<'SHIM_EOF' /opt/harness/shim/codex-responses-shim.mjs
#!/usr/bin/env node
// codex-responses-shim — a tiny local sidecar that exposes the OpenAI *Responses* API
// (which the Codex CLI requires; it no longer supports wire_api="chat") and translates
// each call into an OpenAI *Chat Completions* request against an upstream base URL.
//
//   Codex  --POST /v1/responses-->  this shim  --POST $UPSTREAM/chat/completions-->  recording proxy
//
// Zero dependencies; Node >= 18. Configuration (env):
//   SHIM_UPSTREAM_BASE_URL   upstream OpenAI-compatible base (default: $OPENAI_BASE_URL)
//   SHIM_UPSTREAM_API_KEY    bearer token for upstream        (default: $OPENAI_API_KEY or "proxy")
//   SHIM_HOST / SHIM_PORT    listen address                   (default: 127.0.0.1:4141)
//   SHIM_MODEL               override the model name sent upstream (default: pass through)
//   SHIM_FORWARD_REASONING_EFFORT=1  forward Codex's reasoning.effort as reasoning_effort
//   SHIM_LOG                 append a request/response trace to this file
import http from "node:http";
import fs from "node:fs";
import { randomBytes } from "node:crypto";

const UPSTREAM = (process.env.SHIM_UPSTREAM_BASE_URL || process.env.OPENAI_BASE_URL || "").replace(/\/+$/, "");
const API_KEY = process.env.SHIM_UPSTREAM_API_KEY || process.env.OPENAI_API_KEY || "proxy";
const HOST = process.env.SHIM_HOST || "127.0.0.1";
const PORT = Number(process.env.SHIM_PORT || 4141);
const MODEL_OVERRIDE = process.env.SHIM_MODEL || "";
const FORWARD_REASONING = process.env.SHIM_FORWARD_REASONING_EFFORT === "1";
const LOG_PATH = process.env.SHIM_LOG || "";

if (!UPSTREAM) {
  console.error("codex-responses-shim: set SHIM_UPSTREAM_BASE_URL or OPENAI_BASE_URL (e.g. $PROXY_URL/v1)");
  process.exit(2);
}

const rid = (p) => `${p}_${randomBytes(12).toString("hex")}`;
function log(line) {
  const msg = `[${new Date().toISOString()}] ${line}`;
  if (LOG_PATH) {
    try { fs.appendFileSync(LOG_PATH, msg + "\n"); } catch { /* ignore */ }
  } else {
    console.error(msg);
  }
}

// ---------- Responses input  ->  Chat messages ----------
function textOf(content) {
  if (content == null) return "";
  if (typeof content === "string") return content;
  if (!Array.isArray(content)) return JSON.stringify(content);
  return content.map((p) => {
    if (typeof p === "string") return p;
    if (!p) return "";
    if (["input_text", "output_text", "text", "summary_text", "reasoning_text"].includes(p.type)) return p.text ?? "";
    if (p.type === "refusal") return p.refusal ?? "";
    return "";
  }).join("");
}

function userParts(content) {
  if (typeof content === "string") return content;
  if (!Array.isArray(content)) return textOf(content);
  const parts = [];
  for (const p of content) {
    if (!p) continue;
    if (p.type === "input_text" || p.type === "text" || p.type === "output_text") parts.push({ type: "text", text: p.text ?? "" });
    else if (p.type === "input_image") {
      const url = typeof p.image_url === "string" ? p.image_url : p.image_url?.url;
      if (url) parts.push({ type: "image_url", image_url: { url, detail: p.detail || "auto" } });
    }
  }
  if (parts.length === 0) return "";
  if (parts.every((x) => x.type === "text")) return parts.map((x) => x.text).join("");
  return parts;
}

function argsString(a) {
  if (typeof a === "string") return a;
  if (a == null) return "{}";
  return JSON.stringify(a);
}

function convertInput(body) {
  const messages = [];
  if (body.instructions) messages.push({ role: "system", content: String(body.instructions) });
  const input = body.input;
  if (typeof input === "string") { messages.push({ role: "user", content: input }); return messages; }
  if (!Array.isArray(input)) return messages;

  let pending = null; // assistant message accumulating consecutive tool calls
  const flush = () => { if (pending) { messages.push(pending); pending = null; } };
  for (const item of input) {
    if (!item || typeof item !== "object") continue;
    const type = item.type || (item.role ? "message" : "");
    switch (type) {
      case "message": {
        const role = item.role === "developer" ? "system" : (item.role || "user");
        if (role === "assistant") {
          const text = textOf(item.content);
          if (pending) { pending.content = (pending.content || "") + text; }
          else if (text.length > 0) messages.push({ role: "assistant", content: text });
        } else {
          flush();
          messages.push({ role, content: role === "user" ? userParts(item.content) : textOf(item.content) });
        }
        break;
      }
      case "function_call":
      case "custom_tool_call": {
        if (!pending) pending = { role: "assistant", content: null, tool_calls: [] };
        const args = type === "function_call" ? argsString(item.arguments) : JSON.stringify({ input: item.input ?? "" });
        pending.tool_calls.push({ id: item.call_id || item.id || rid("call"), type: "function", function: { name: item.name, arguments: args } });
        break;
      }
      case "local_shell_call": {
        if (!pending) pending = { role: "assistant", content: null, tool_calls: [] };
        pending.tool_calls.push({ id: item.call_id || item.id || rid("call"), type: "function", function: { name: "shell", arguments: JSON.stringify(item.action ?? {}) } });
        break;
      }
      case "function_call_output":
      case "custom_tool_call_output":
      case "local_shell_call_output": {
        flush();
        const out = item.output;
        const content = typeof out === "string" ? out : (Array.isArray(out) ? textOf(out) : JSON.stringify(out ?? ""));
        messages.push({ role: "tool", tool_call_id: item.call_id, content: content.length > 0 ? content : "(no output)" });
        break;
      }
      default:
        // reasoning, item_reference, web_search_call, ... have no chat-completions equivalent
        break;
    }
  }
  flush();
  return messages;
}

// ---------- tools ----------
// Codex >= 0.15x declares tools as `additional_tools` input items whose `tools` array holds
// `namespace` groups ({type:"namespace", name, tools:[...]}) of function/custom tools. Flatten them.
// Chat-completions tool names must be flat, so nested tools keep their bare name; the namespace is
// remembered so the function_call we emit back can be re-qualified if needed.
// Verified against Codex 0.156.1: tools outside the default `functions` namespace (e.g. the `collaboration`
// agent tools) are routed only when the function_call item carries a `namespace` field ("field" style);
// bare or dotted names are rejected with "unsupported call".
const NAMESPACE_CALL_STYLE = process.env.SHIM_NAMESPACE_CALL_STYLE || "field"; // "field" | "bare" | "dotted"
function collectTools(body) {
  const flat = [];
  const nsOf = new Map();
  const visit = (list, ns) => {
    for (const t of list || []) {
      if (!t || typeof t !== "object") continue;
      if (t.type === "namespace") { visit(t.tools, t.name || null); continue; }
      if (t.name) nsOf.set(t.name, ns);
      flat.push(t);
    }
  };
  visit(body.tools, null);
  if (Array.isArray(body.input)) for (const item of body.input) if (item?.type === "additional_tools") visit(item.tools, null);
  return { flat, nsOf };
}
function qualifyName(name, nsOf) {
  const ns = nsOf.get(name);
  if (NAMESPACE_CALL_STYLE === "dotted" && ns && ns !== "functions") return `${ns}.${name}`;
  return name;
}
// Extra fields for a tool-call output item whose tool lives in a non-default namespace.
function namespaceFields(name, nsOf) {
  const ns = nsOf.get(name);
  if (NAMESPACE_CALL_STYLE === "field" && ns && ns !== "functions") return { namespace: ns };
  return {};
}
function convertTools(tools) {
  const out = [];
  const customNames = new Set();
  for (const t of tools || []) {
    if (!t || typeof t !== "object") continue;
    if (t.type === "function" && t.name) {
      out.push({ type: "function", function: { name: t.name, description: t.description || "", parameters: t.parameters || { type: "object", properties: {} } } });
    } else if (t.type === "custom" && t.name) {
      // Freeform/grammar tools (e.g. Codex's apply_patch) become a function with one raw string argument.
      customNames.add(t.name);
      out.push({
        type: "function",
        function: {
          name: t.name,
          description: `${t.description || ""}\nPass the complete raw tool input as the string field \`input\`.`.trim(),
          parameters: { type: "object", properties: { input: { type: "string", description: "Raw tool input" } }, required: ["input"] },
        },
      });
    }
    // web_search, local_shell, image_generation, ... are dropped (no chat-completions equivalent)
  }
  return { tools: out, customNames };
}

function convertToolChoice(tc) {
  if (!tc || tc === "auto") return "auto";
  if (tc === "none" || tc === "required") return tc;
  if (typeof tc === "object" && tc.type === "function" && tc.name) return { type: "function", function: { name: tc.name } };
  return "auto";
}

// ---------- Chat stream  ->  Responses SSE ----------
async function handleResponses(req, res, body) {
  const messages = convertInput(body);
  const { flat, nsOf } = collectTools(body);
  const { tools, customNames } = convertTools(flat);
  const model = MODEL_OVERRIDE || body.model || "gpt-4o";
  const chatReq = { model, messages, stream: true, stream_options: { include_usage: true } };
  if (tools.length > 0) {
    chatReq.tools = tools;
    chatReq.tool_choice = convertToolChoice(body.tool_choice);
    if (typeof body.parallel_tool_calls === "boolean") chatReq.parallel_tool_calls = body.parallel_tool_calls;
  }
  if (Number.isFinite(body.max_output_tokens)) chatReq.max_tokens = body.max_output_tokens;
  if (typeof body.temperature === "number") chatReq.temperature = body.temperature;
  if (FORWARD_REASONING && body.reasoning?.effort) chatReq.reasoning_effort = body.reasoning.effort;

  const toolKinds = flat.map((t) => `${t?.type}:${t?.name || ""}`).join(",");
  const itemKinds = Array.isArray(body.input) ? [...new Set(body.input.map((i) => i?.type || i?.role))].join(",") : typeof body.input;
  log(`-> chat/completions model=${model} messages=${messages.length} tools=${tools.length} [in: tools=${toolKinds} items=${itemKinds}]`);
  if (process.env.SHIM_DEBUG_DIR) {
    try {
      fs.mkdirSync(process.env.SHIM_DEBUG_DIR, { recursive: true });
      const stamp = `${Date.now()}-${rid("r")}`;
      fs.writeFileSync(`${process.env.SHIM_DEBUG_DIR}/${stamp}.responses.json`, JSON.stringify(body, null, 2));
      fs.writeFileSync(`${process.env.SHIM_DEBUG_DIR}/${stamp}.chat.json`, JSON.stringify(chatReq, null, 2));
    } catch { /* ignore */ }
  }
  let upstream;
  try {
    upstream = await fetch(`${UPSTREAM}/chat/completions`, {
      method: "POST",
      headers: { "content-type": "application/json", authorization: `Bearer ${API_KEY}`, accept: "text/event-stream, application/json" },
      body: JSON.stringify(chatReq),
    });
  } catch (err) {
    log(`upstream connect error: ${err?.message || err}`);
    res.writeHead(502, { "content-type": "application/json" });
    res.end(JSON.stringify({ error: { message: `shim: upstream unreachable: ${err?.message || err}`, type: "server_error" } }));
    return;
  }
  if (!upstream.ok) {
    const text = await upstream.text().catch(() => "");
    log(`<- upstream ${upstream.status}: ${text.slice(0, 300)}`);
    res.writeHead(upstream.status, { "content-type": "application/json" });
    res.end(text || JSON.stringify({ error: { message: `upstream HTTP ${upstream.status}`, type: "server_error" } }));
    return;
  }

  res.writeHead(200, { "content-type": "text/event-stream", "cache-control": "no-cache", connection: "keep-alive" });
  const responseId = rid("resp");
  let seq = 0;
  const send = (type, payload) => { res.write(`event: ${type}\ndata: ${JSON.stringify({ type, sequence_number: seq++, ...payload })}\n\n`); };
  const baseResponse = () => ({ id: responseId, object: "response", created_at: Math.floor(Date.now() / 1000), model, status: "in_progress", output: [] });
  send("response.created", { response: baseResponse() });
  send("response.in_progress", { response: baseResponse() });

  // accumulation state
  let text = "";
  let msgItemId = null;
  let outputIndex = 0;
  const toolCalls = new Map(); // index -> {id,name,args}
  let usage = null;
  let upstreamError = null;
  const output = [];

  const onTextDelta = (delta) => {
    if (!delta) return;
    if (msgItemId === null) {
      msgItemId = rid("msg");
      send("response.output_item.added", { output_index: outputIndex, item: { id: msgItemId, type: "message", role: "assistant", status: "in_progress", content: [] } });
      send("response.content_part.added", { item_id: msgItemId, output_index: outputIndex, content_index: 0, part: { type: "output_text", text: "", annotations: [] } });
    }
    text += delta;
    send("response.output_text.delta", { item_id: msgItemId, output_index: outputIndex, content_index: 0, delta });
  };
  const onReasoningDelta = (delta) => {
    if (delta) send("response.reasoning_summary_text.delta", { item_id: rid("rs"), output_index: 0, summary_index: 0, delta });
  };
  const onToolCallDelta = (tc) => {
    const idx = tc.index ?? 0;
    let cur = toolCalls.get(idx);
    if (!cur) { cur = { id: tc.id || rid("call"), name: "", args: "" }; toolCalls.set(idx, cur); }
    if (tc.id) cur.id = tc.id;
    if (tc.function?.name) cur.name += tc.function.name;
    if (tc.function?.arguments) cur.args += tc.function.arguments;
  };
  const consumeChoice = (choice) => {
    const d = choice?.delta || choice?.message || {};
    if (typeof d.content === "string") onTextDelta(d.content);
    else if (Array.isArray(d.content)) onTextDelta(d.content.map((p) => p?.text ?? "").join(""));
    const reasoning = d.reasoning_content ?? d.reasoning;
    if (typeof reasoning === "string") onReasoningDelta(reasoning);
    if (Array.isArray(d.tool_calls)) for (const tc of d.tool_calls) onToolCallDelta(tc);
  };

  const ctype = upstream.headers.get("content-type") || "";
  try {
    if (ctype.includes("text/event-stream")) {
      const reader = upstream.body.getReader();
      const decoder = new TextDecoder();
      let buf = "";
      for (;;) {
        const { value, done } = await reader.read();
        if (done) break;
        buf += decoder.decode(value, { stream: true });
        let nl;
        while ((nl = buf.indexOf("\n")) >= 0) {
          const line = buf.slice(0, nl).replace(/\r$/, "");
          buf = buf.slice(nl + 1);
          if (!line.startsWith("data:")) continue;
          const data = line.slice(5).trim();
          if (!data || data === "[DONE]") continue;
          let chunk;
          try { chunk = JSON.parse(data); } catch { continue; }
          if (chunk.error) { upstreamError = chunk.error; break; }
          if (chunk.usage) usage = chunk.usage;
          for (const choice of chunk.choices || []) consumeChoice(choice);
        }
        if (upstreamError) break;
      }
    } else {
      const full = await upstream.json();
      if (full.error) upstreamError = full.error;
      if (full.usage) usage = full.usage;
      for (const choice of full.choices || []) consumeChoice(choice);
    }
  } catch (err) {
    upstreamError = { message: `shim: upstream stream error: ${err?.message || err}` };
  }

  if (upstreamError) {
    log(`<- upstream error: ${JSON.stringify(upstreamError).slice(0, 300)}`);
    send("response.failed", { response: { ...baseResponse(), status: "failed", error: { code: upstreamError.code || "server_error", message: upstreamError.message || String(upstreamError) } } });
    res.end();
    return;
  }

  if (msgItemId !== null) {
    const item = { id: msgItemId, type: "message", role: "assistant", status: "completed", content: [{ type: "output_text", text, annotations: [] }] };
    send("response.output_text.done", { item_id: msgItemId, output_index: outputIndex, content_index: 0, text });
    send("response.content_part.done", { item_id: msgItemId, output_index: outputIndex, content_index: 0, part: { type: "output_text", text, annotations: [] } });
    send("response.output_item.done", { output_index: outputIndex, item });
    output.push(item);
    outputIndex += 1;
  }
  for (const [, tc] of [...toolCalls.entries()].sort((a, b) => a[0] - b[0])) {
    let item;
    if (customNames.has(tc.name)) {
      let input = tc.args;
      try { const parsed = JSON.parse(tc.args); if (parsed && typeof parsed === "object" && typeof parsed.input === "string") input = parsed.input; } catch { /* raw */ }
      item = { id: rid("ctc"), type: "custom_tool_call", call_id: tc.id, name: qualifyName(tc.name, nsOf), ...namespaceFields(tc.name, nsOf), input, status: "completed" };
    } else {
      item = { id: rid("fc"), type: "function_call", call_id: tc.id, name: qualifyName(tc.name, nsOf), ...namespaceFields(tc.name, nsOf), arguments: tc.args || "{}", status: "completed" };
    }
    send("response.output_item.added", { output_index: outputIndex, item: { ...item, status: "in_progress" } });
    send("response.output_item.done", { output_index: outputIndex, item });
    output.push(item);
    outputIndex += 1;
  }
  const inTok = usage?.prompt_tokens ?? 0;
  const outTok = usage?.completion_tokens ?? 0;
  const finalUsage = {
    input_tokens: inTok,
    input_tokens_details: { cached_tokens: usage?.prompt_tokens_details?.cached_tokens ?? 0 },
    output_tokens: outTok,
    output_tokens_details: { reasoning_tokens: usage?.completion_tokens_details?.reasoning_tokens ?? 0 },
    total_tokens: usage?.total_tokens ?? inTok + outTok,
  };
  send("response.completed", { response: { ...baseResponse(), status: "completed", output, usage: finalUsage } });
  res.end();
  log(`<- completed text=${text.length}ch tool_calls=${toolCalls.size} usage=${inTok}/${outTok}`);
}

// ---------- passthrough for anything else (e.g. GET /v1/models) ----------
async function passthrough(req, res, rawBody) {
  const path = req.url.replace(/^\/v1(?=\/|$)/, "");
  try {
    const r = await fetch(`${UPSTREAM}${path}`, {
      method: req.method,
      headers: { "content-type": req.headers["content-type"] || "application/json", authorization: `Bearer ${API_KEY}` },
      body: ["GET", "HEAD"].includes(req.method) ? undefined : rawBody,
    });
    res.writeHead(r.status, { "content-type": r.headers.get("content-type") || "application/json" });
    res.end(Buffer.from(await r.arrayBuffer()));
  } catch (err) {
    res.writeHead(502, { "content-type": "application/json" });
    res.end(JSON.stringify({ error: { message: `shim: upstream unreachable: ${err?.message || err}` } }));
  }
}

const server = http.createServer((req, res) => {
  const chunks = [];
  req.on("data", (c) => chunks.push(c));
  req.on("end", async () => {
    const raw = Buffer.concat(chunks);
    const url = req.url.split("?")[0];
    try {
      if (req.method === "GET" && (url === "/healthz" || url === "/")) {
        res.writeHead(200, { "content-type": "application/json" });
        res.end(JSON.stringify({ ok: true, upstream: UPSTREAM }));
        return;
      }
      if (req.method === "POST" && (url === "/v1/responses" || url === "/responses")) {
        let body;
        try { body = JSON.parse(raw.toString("utf8") || "{}"); } catch {
          res.writeHead(400, { "content-type": "application/json" });
          res.end(JSON.stringify({ error: { message: "invalid JSON" } }));
          return;
        }
        await handleResponses(req, res, body);
        return;
      }
      await passthrough(req, res, raw);
    } catch (err) {
      log(`handler error: ${err?.stack || err}`);
      if (!res.headersSent) res.writeHead(500, { "content-type": "application/json" });
      res.end(JSON.stringify({ error: { message: `shim: ${err?.message || err}` } }));
    }
  });
});

server.listen(PORT, HOST, () => log(`codex-responses-shim listening on http://${HOST}:${PORT} -> ${UPSTREAM}`));
for (const sig of ["SIGINT", "SIGTERM"]) process.on(sig, () => { server.close(); process.exit(0); });
SHIM_EOF
RUN set -eux; node --check /opt/harness/shim/codex-responses-shim.mjs; \
    printf '#!/bin/sh\nexec node /opt/harness/shim/codex-responses-shim.mjs "$@"\n' > /opt/harness/bin/codex-responses-shim; \
    chmod +x /opt/harness/bin/codex-responses-shim; \
    printf 'export PATH=/opt/harness/bin:/opt/harness/node/bin:$PATH\nexport CODEX_HOME=${CODEX_HOME:-/opt/harness/codex-home}\n' > /etc/profile.d/lazycodex-harness.sh
